func registerRateLimitRoutes(g *gin.RouterGroup, ctx *svc.ServiceContext) {
	g.GET("/", rateLimit.RateLimitsListHandler(ctx))
	g.GET("/:id", rateLimit.RateLimitGetHandler(ctx))
	g.PUT("/", rateLimit.RateLimitUpsertHandler(ctx))
	g.DELETE("/:id", rateLimit.RateLimitDeleteHandler(ctx))
	g.POST("/preview", rateLimit.RateLimitPreviewHandler(ctx))
}

