// ============================================================================
// Workspace 路由注册
// ============================================================================
func registerWorkspaceRoutes(g *gin.RouterGroup, ctx *svc.ServiceContext) {
	g.GET("/configs", workspace.WorkspaceConfigsListHandler(ctx))
	g.GET("/published", workspace.WorkspacePublishedListHandler(ctx))
	g.GET("/:objectKey/config", workspace.WorkspaceConfigGetHandler(ctx))
	g.PUT("/:objectKey/config", workspace.WorkspaceConfigSaveHandler(ctx))
	g.DELETE("/:objectKey/config", workspace.WorkspaceConfigDeleteHandler(ctx))
	g.POST("/:objectKey/publish", workspace.WorkspacePublishHandler(ctx))
	g.POST("/:objectKey/unpublish", workspace.WorkspaceUnpublishHandler(ctx))
	g.GET("/:objectKey/versions", workspace.WorkspaceVersionsHandler(ctx))
	g.GET("/:objectKey/versions/:versionId", workspace.WorkspaceVersionDetailHandler(ctx))
	g.POST("/:objectKey/rollback", workspace.WorkspaceRollbackHandler(ctx))
}
